import React, { useEffect, useState } from 'react';
import {
  Box, Typography, Grid, Paper,
  Dialog, DialogTitle, DialogContent, DialogActions,
  TextField, Button, Alert, Snackbar, IconButton
} from '@mui/material';
import AddIcon from '@mui/icons-material/Add';
import { useAuth } from './AuthContext';

const CompanyProfiles = () => {
  const { user } = useAuth();
  const [companies, setCompanies] = useState([]);
  const [openDialog, setOpenDialog] = useState(false);
  const [selectedCompany, setSelectedCompany] = useState(null);
  const [editMode, setEditMode] = useState(false);
  const [passwordConfirm, setPasswordConfirm] = useState('');
  const [passwordError, setPasswordError] = useState('');
  const [passwordVerified, setPasswordVerified] = useState(false);
  const [verifying, setVerifying] = useState(false);
  const [snackbar, setSnackbar] = useState({
    open: false,
    message: '',
    severity: 'success'
  });
  const [companyForm, setCompanyForm] = useState({
    name: '',
    address: '',
    phoneNumber: ''
  });

  useEffect(() => {
    fetchCompanies();
  }, []);

  const fetchCompanies = async () => {
    try {
      const response = await fetch('http://localhost:8080/companies/all');
      if (!response.ok) throw new Error('Failed to fetch companies');
      const data = await response.json();

      // Sort companies alphabetically by name
      const sortedCompanies = data.sort((a, b) => a.name.localeCompare(b.name));

      setCompanies(sortedCompanies);
    } catch (err) {
      console.error('Error fetching companies:', err);
      handleSnackbar('Error fetching companies', 'error');
    }
  };

  const handleOpenAddDialog = () => {
    setCompanyForm({ name: '', address: '', phoneNumber: '' });
    setEditMode(false);
    setPasswordConfirm('');
    setPasswordError('');
    setPasswordVerified(false);
    setOpenDialog(true);
  };

  const handleOpenViewDialog = (company) => {
    setSelectedCompany(company);
    setCompanyForm({
      name: company.name,
      address: company.address,
      phoneNumber: company.phoneNumber
    });
    setEditMode(false);
    setPasswordConfirm('');
    setPasswordError('');
    setPasswordVerified(false);
    setOpenDialog(true);
  };

  const handleCloseDialog = () => {
    setOpenDialog(false);
    setSelectedCompany(null);
    setCompanyForm({ name: '', address: '', phoneNumber: '' });
    setEditMode(false);
    setPasswordConfirm('');
    setPasswordError('');
    setPasswordVerified(false);
  };

  const handleFormChange = (e) => {
    const { name, value } = e.target;
    setCompanyForm((prev) => ({ ...prev, [name]: value }));
  };

  const handlePasswordChange = (e) => {
    setPasswordConfirm(e.target.value);
    setPasswordError('');
    setPasswordVerified(false);
  };

  const handleSnackbar = (message, severity = 'success') => {
    setSnackbar({
      open: true,
      message,
      severity
    });
  };

  const closeSnackbar = () => {
    setSnackbar({ ...snackbar, open: false });
  };

  const verifyPassword = async () => {
    if (!passwordConfirm) {
      setPasswordError('Please enter your password');
      return false;
    }

    setVerifying(true);
    try {
      const response = await fetch('http://localhost:8080/worker/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ 
          username: user.username, 
          password: passwordConfirm 
        }),
      });

      const data = await response.json();

      if (response.ok) {
        setPasswordVerified(true);
        setPasswordError('');
        return true;
      } else {
        setPasswordVerified(false);
        setPasswordError('Incorrect password');
        return false;
      }
    } catch (error) {
      console.error('Error verifying password:', error);
      setPasswordVerified(false);
      setPasswordError('Error verifying password');
      return false;
    } finally {
      setVerifying(false);
    }
  };

  const handleSave = async () => {
    // Verify password if not already verified
    if (!passwordVerified) {
      const isVerified = await verifyPassword();
      if (!isVerified) return;
    }

    try {
      const response = await fetch('http://localhost:8080/companies/add', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(companyForm),
      });

      if (!response.ok) throw new Error('Failed to add company');

      handleCloseDialog();
      fetchCompanies();
      handleSnackbar('Company added successfully');
    } catch (err) {
      console.error('Error saving company:', err);
      handleSnackbar('Error saving company', 'error');
    }
  };

  const handleEditClick = async () => {
    const isVerified = await verifyPassword();
    if (isVerified) {
      setEditMode(true);
    }
  };

  const handleUpdate = async () => {
    // Verify password if not already verified
    if (!passwordVerified) {
      const isVerified = await verifyPassword();
      if (!isVerified) return;
    }

    try {
      const response = await fetch(`http://localhost:8080/companies/${selectedCompany.id}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(companyForm),
      });

      if (!response.ok) throw new Error('Failed to update company');

      handleCloseDialog();
      fetchCompanies();
      handleSnackbar('Company updated successfully');
    } catch (err) {
      console.error('Error updating company:', err);
      handleSnackbar('Error updating company', 'error');
    }
  };

  const handleDelete = async () => {
    // Verify password if not already verified
    if (!passwordVerified) {
      const isVerified = await verifyPassword();
      if (!isVerified) return;
    }

    try {
      const response = await fetch(`http://localhost:8080/companies/${selectedCompany.id}`, {
        method: 'DELETE',
      });

      if (!response.ok) throw new Error('Failed to delete company');

      handleCloseDialog();
      fetchCompanies();
      handleSnackbar('Company deleted successfully');
    } catch (err) {
      console.error('Error deleting company:', err);
      handleSnackbar('Error deleting company', 'error');
    }
  };

  // Function to check if form is valid for adding/editing
  const isFormValid = () => {
    return companyForm.name && companyForm.address && companyForm.phoneNumber;
  };

  // Function to verify password and then take action
  const verifyAndExecute = async (action) => {
    if (!passwordVerified) {
      const isVerified = await verifyPassword();
      if (isVerified) {
        action();
      }
    } else {
      action();
    }
  };

  return (
    <Box sx={{ p: 3 }}>
      <Typography variant="h4" align="center" gutterBottom sx={{ fontWeight: 'bold', mb: 4 }}>
        Company Profiles
      </Typography>
      <Grid container spacing={2}>
        {companies.map((company) => (
          <Grid item xs={12} sm={6} md={4} lg={2} key={company.id}>
            <Paper
              elevation={3}
              sx={{ p: 2, textAlign: 'center', cursor: 'pointer' }}
              onClick={() => handleOpenViewDialog(company)}
            >
              {company.name}
            </Paper>
          </Grid>
        ))}
        <Grid item xs={12} sm={6} md={4} lg={2}>
          <Paper
            elevation={3}
            sx={{ p: 2, textAlign: 'center', cursor: 'pointer' }}
            onClick={handleOpenAddDialog}
          >
            <AddIcon fontSize="large" />
          </Paper>
        </Grid>
      </Grid>

      {/* Dialog */}
      <Dialog open={openDialog} onClose={handleCloseDialog}>
        <DialogTitle>
          {selectedCompany ? (editMode ? "Edit Company" : "Company Details") : "Add New Company"}
        </DialogTitle>
        <DialogContent>
          <TextField
            label="Company Name"
            name="name"
            value={companyForm.name}
            onChange={handleFormChange}
            fullWidth
            margin="dense"
            disabled={!editMode && selectedCompany}
            required
            error={!companyForm.name && (editMode || !selectedCompany)}
            helperText={!companyForm.name && (editMode || !selectedCompany) ? "Company name is required" : ""}
          />
          <TextField
            label="Address"
            name="address"
            value={companyForm.address}
            onChange={handleFormChange}
            fullWidth
            margin="dense"
            disabled={!editMode && selectedCompany}
            required
            error={!companyForm.address && (editMode || !selectedCompany)}
            helperText={!companyForm.address && (editMode || !selectedCompany) ? "Address is required" : ""}
          />
          <TextField
            label="Phone Number"
            name="phoneNumber"
            value={companyForm.phoneNumber}
            onChange={handleFormChange}
            fullWidth
            margin="dense"
            disabled={!editMode && selectedCompany}
            required
            error={!companyForm.phoneNumber && (editMode || !selectedCompany)}
            helperText={!companyForm.phoneNumber && (editMode || !selectedCompany) ? "Phone number is required" : ""}
          />

          {/* Password field for verification */}
          <TextField
            label="Enter Your Password"
            type="password"
            value={passwordConfirm}
            onChange={handlePasswordChange}
            fullWidth
            margin="dense"
            required
            error={!!passwordError}
            helperText={passwordError || "Enter your password to make changes"}
            sx={{ mt: 2 }}
            disabled={passwordVerified}
          />

          {/* Verification button */}
          {!passwordVerified && (
            <Button 
              onClick={verifyPassword} 
              variant="outlined" 
              color="primary"
              disabled={!passwordConfirm || verifying}
              fullWidth
              sx={{ mt: 1 }}
            >
              {verifying ? "Verifying..." : "Verify Password"}
            </Button>
          )}

          {passwordVerified && (
            <Alert severity="success" sx={{ mt: 1 }}>
              Password verified successfully!
            </Alert>
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={handleCloseDialog} color="primary">
            Cancel
          </Button>
          {selectedCompany && !editMode && (
            <>
              <Button 
                onClick={handleEditClick} 
                variant="contained" 
                color="primary"
                disabled={!passwordConfirm || verifying || (!passwordVerified && !!passwordConfirm)}
              >
                Edit
              </Button>
              <Button 
                onClick={handleDelete} 
                variant="contained" 
                color="error"
                disabled={!passwordConfirm || verifying || (!passwordVerified && !!passwordConfirm)}
              >
                Delete
              </Button>
            </>
          )}
          {editMode && selectedCompany && (
            <Button 
              onClick={handleUpdate} 
              variant="contained" 
              color="primary"
              disabled={!isFormValid() || (!passwordVerified && !passwordConfirm) || verifying}
            >
              Save Changes
            </Button>
          )}
          {!selectedCompany && (
            <Button 
              onClick={handleSave} 
              variant="contained" 
              color="primary"
              disabled={!isFormValid() || (!passwordVerified && !passwordConfirm) || verifying}
            >
              Save
            </Button>
          )}
        </DialogActions>
      </Dialog>

      {/* Snackbar for notifications */}
      <Snackbar
        open={snackbar.open}
        autoHideDuration={6000}
        onClose={closeSnackbar}
        anchorOrigin={{ vertical: 'bottom', horizontal: 'center' }}
      >
        <Alert 
          onClose={closeSnackbar} 
          severity={snackbar.severity} 
          sx={{ width: '100%' }}
        >
          {snackbar.message}
        </Alert>
      </Snackbar>
    </Box>
  );
};

export default CompanyProfiles;
